Generated from this rust (the function calls and returns `@dbsp.timestamp.year()` when the input value is non-null and returns `i64::MIN` if the input value is null)
```rust
let mut builder = FunctionBuilder::new(layout_cache.clone());
let input = builder.add_input(timestamp);
let output = builder.add_output(i64);

let return_block = builder.create_block();
builder.add_block_param(return_block, ColumnType::I64);
let timestamp_non_null = builder.create_block();

let timestamp_is_null = builder.is_null(input, 0);
let i64_min = builder.constant(Constant::I64(i64::MIN));
builder.branch(
    timestamp_is_null,
    return_block,
    [i64_min],
    timestamp_non_null,
    [],
);

builder.move_to(timestamp_non_null);
let timestamp = builder.load(input, 0);
let year = builder.add_expr(Call::new(
    "dbsp.timestamp.year".into(),
    vec![timestamp],
    vec![ArgType::Scalar(ColumnType::Timestamp)],
    ColumnType::I64,
));
builder.jump(return_block, [year]);

builder.move_to(return_block);
let year = builder.block_params(return_block)[0].0;
builder.store(output, 0, year);
builder.ret_unit();

builder.build()
```

We have a proxy class 
```
class Row
{
 public:
  struct Pointer
  {
    inline Pointer() = default;

    // Pointer(uint8_t*) implicitly makes old code compatible with the string table impl;
    inline Pointer(uint8_t* d) : data(d)
    {
    }
    inline Pointer(uint8_t* d, StringStore* s) : data(d), strings(s)
    {
    }
    inline Pointer(uint8_t* d, StringStore* s, UserDataStore* u) : data(d), strings(s), userDataStore(u)
    {
    }
    uint8_t* data = nullptr;
    StringStore* strings = nullptr;
    UserDataStore* userDataStore = nullptr;
  };
```
Note, first ctor is not explicit, and doesn't respect anything about ```StringStore```
when using ```Row::setData``` on pure byte memory, all the ```StringStore``` does not work

This PR removes ugly ```RowGroup::setData``` and makes Pointer ctor explicit, to highlight all the places we need to inspect
